    decay = 0.85 + 0.15 * (iteration / n_iterations)
    pheromone *= decay
    avg_cost = np.mean(costs)
    std_dev = np.std(costs)
    for i, solution in enumerate(solutions):
        cost = costs[i]
        deposit = (1.0 / (cost + 1e-10)) * (1 + (std_dev / avg_cost))
        for route in solution:
            for j in range(len(route) - 1):
                pheromone[route[j], route[j + 1]] += deposit
                if j == 0:
                    pheromone[route[-1], route[0]] += deposit * 0.75  # Increased depot transition boost
    pheromone = np.maximum(pheromone, 1e-10)
    return pheromone

