def update_pheromone(pheromone, solutions, costs, iteration, n_iterations):
    decay = 0.9
    pheromone *= decay
    edge_usage = np.zeros_like(pheromone)
    for i, solution in enumerate(solutions):
        cost = costs[i]
        deposit = 1.0 / (cost + 1e-10)
        for route in solution:
            for j in range(len(route) - 1):
                edge_usage[route[j], route[j + 1]] += 1
                if j == len(route) - 2:
                    edge_usage[route[-1], route[0]] += 1
    pheromone += deposit * edge_usage
    pheromone = np.maximum(pheromone, 1e-10)
    return pheromone

